1	package com.example.starter.service.impl;
2	
3	import java.util.Map;
4	import java.util.function.Supplier;
5	
6	import org.springframework.dao.DuplicateKeyException;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.stereotype.Component;
9	import org.springframework.transaction.PlatformTransactionManager;
10	import org.springframework.transaction.support.TransactionTemplate;
11	
12	import com.example.starter.support.ApiException;
13	import com.example.starter.support.Fingerprints;
14	import com.example.starter.service.IdempotencyExecutor;
15	import com.example.starter.service.Outcome;
16	import com.fasterxml.jackson.databind.ObjectMapper;
17	
18	/**
19	 * 基于 {@code idempotent_request} 唯一主键的幂等执行器。
20	 *
21	 * <p>首次执行：业务动作与台账插入在同一事务，提交后生效；并发同键的落败方整事务回滚并重放获胜结果。
22	 * 业务失败：业务事务回滚（不改变工序状态），失败结果另起事务登记，同键同参重放仍返回首次失败结果。
23	 * 同键异参：不执行动作、台账不变，直接 409。
24	 */
25	@Component
26	public class JdbcIdempotencyExecutor implements IdempotencyExecutor {
27	
28	    private static final String SELECT_SQL =
29	            "SELECT operation, fingerprint, status_code, response_type, response_json "
30	                    + "FROM idempotent_request WHERE request_id = ?";
31	    private static final String INSERT_SQL =
32	            "INSERT INTO idempotent_request (request_id, operation, fingerprint, status_code, "
33	                    + "response_type, response_json) VALUES (?, ?, ?, ?, ?, ?)";
34	
35	    private final JdbcTemplate jdbcTemplate;
36	    private final TransactionTemplate transactionTemplate;
37	    private final ObjectMapper objectMapper;
38	
39	    public JdbcIdempotencyExecutor(JdbcTemplate jdbcTemplate,
40	                                   PlatformTransactionManager transactionManager,
41	                                   ObjectMapper objectMapper) {
42	        this.jdbcTemplate = jdbcTemplate;
43	        this.transactionTemplate = new TransactionTemplate(transactionManager);
44	        this.objectMapper = objectMapper;
45	    }
46	
47	    @Override
48	    public Outcome execute(String requestId, String operation, Object businessFields, Supplier<Outcome> action) {
49	        String fingerprint = fingerprint(requestId, operation, businessFields);
50	        try {
51	            return transactionTemplate.execute(status -> doInTransaction(requestId, operation, fingerprint, action));
52	        } catch (LostIdempotencyRaceException lostRace) {
53	            // 并发同键落败：本事务已回滚，转读获胜方首次结果。
54	            return resolveExisting(requireEntry(requestId), fingerprint);
55	        } catch (ApiException businessFailure) {
56	            // 业务动作被拒绝：业务事务已回滚，另起事务登记首次失败结果，失败也幂等。
57	            return recordFailure(requestId, operation, fingerprint, businessFailure);
58	        }
59	    }
60	
61	    private Outcome doInTransaction(String requestId, String operation, String fingerprint,
62	                                    Supplier<Outcome> action) {
63	        LedgerEntry existing = findEntry(requestId);
64	        if (existing != null) {
65	            return resolveExisting(existing, fingerprint);
66	        }
67	        Outcome outcome;
68	        try {
69	            outcome = action.get();
70	        } catch (DuplicateKeyException businessUniqueRace) {
71	            // 业务唯一约束冲突（如并发同键重复提交撞 attempt/守卫约束）：本事务回滚，按落败处理。
72	            throw new LostIdempotencyRaceException();
73	        }
74	        try {
75	            insertEntry(requestId, operation, fingerprint, outcome);
76	        } catch (DuplicateKeyException lostRace) {
77	            // 并发同键：唯一约束冲突，本事务必将回滚，抛出后由外层在新事务中读取获胜结果。
78	            throw new LostIdempotencyRaceException();
79	        }
80	        return outcome;
81	    }
82	
83	    private Outcome resolveExisting(LedgerEntry existing, String fingerprint) {
84	        if (!existing.fingerprint().equals(fingerprint)) {
85	            // 同键异参：409，动作未执行、台账不变。
86	            return Outcome.of(409, Map.of(
87	                    "errorCode", "IDEMPOTENCY_KEY_CONFLICT",
88	                    "message", "requestId 已用于不同的业务参数"));
89	        }
90	        return Outcome.replay(existing.statusCode(), parseJson(existing.responseType(), existing.responseJson()));
91	    }
92	
93	    private Outcome recordFailure(String requestId, String operation, String fingerprint, ApiException failure) {
94	        Outcome failed = Outcome.of(failure.getStatus(),
95	                Map.of("errorCode", failure.getErrorCode(), "message", failure.getMessage()));
96	        try {
97	            transactionTemplate.executeWithoutResult(status -> {
98	                if (findEntry(requestId) != null) {
99	                    // 并发场景获胜方已抢先登记，不在本事务插入以免唯一冲突。
100	                    throw new LostIdempotencyRaceException();
101	                }
102	                insertEntry(requestId, operation, fingerprint, failed);
103	            });
104	            return failed;
105	        } catch (LostIdempotencyRaceException | DuplicateKeyException winnerCommittedFirst) {
106	            return resolveExisting(requireEntry(requestId), fingerprint);
107	        }
108	    }
109	
110	    private String fingerprint(String requestId, String operation, Object businessFields) {
111	        byte[] json;
112	        try {
113	            json = objectMapper.writeValueAsBytes(businessFields);
114	        } catch (Exception e) {
115	            throw new IllegalStateException("业务字段序列化失败", e);
116	        }
117	        return Fingerprints.sha256(requestId, operation, json);
118	    }
119	
120	    private void insertEntry(String requestId, String operation, String fingerprint, Outcome outcome) {
121	        String responseJson;
122	        try {
123	            responseJson = objectMapper.writeValueAsString(outcome.body());
124	        } catch (Exception e) {
125	            throw new IllegalStateException("响应序列化失败", e);
126	        }
127	        jdbcTemplate.update(INSERT_SQL, requestId, operation, fingerprint, outcome.status(),
128	                outcome.body().getClass().getName(), responseJson);
129	    }
130	
131	    private LedgerEntry findEntry(String requestId) {
132	        var rows = jdbcTemplate.query(SELECT_SQL, (rs, rowNum) -> new LedgerEntry(
133	                rs.getString("operation"),
134	                rs.getString("fingerprint"),
135	                rs.getInt("status_code"),
136	                rs.getString("response_type"),
137	                rs.getString("response_json")), requestId);
138	        return rows.isEmpty() ? null : rows.get(0);
139	    }
140	
141	    private LedgerEntry requireEntry(String requestId) {
