22	
23	    private String prepareTightenedCard(String cardNo, String station) {
24	        service.registerTool(TestRequests.tool("T1", TestRequests.TODAY));
25	        service.dispatch(TestRequests.singlePoint("d-" + cardNo, cardNo, station, "N", "P1", "100.000"));
26	        service.measure(TestRequests.torque("m-" + cardNo, cardNo, "P1", "100", "op1", "T1"));
27	        return cardNo;
28	    }
