30	    @Test
31	    @DisplayName("派工同键同参重放返回首次结果，不重复建卡/不重复占工位")
32	    void dispatchReplay() {
33	        var request = TestRequests.singlePoint("req-idem-d", "CARD-E1", "S1", "N", "P1", "100.000");
34	        Outcome first = service.dispatch(request);
35	        assertThat(first.status()).isEqualTo(201);
36	        Outcome replay = service.dispatch(request);
37	        assertThat(replay.status()).isEqualTo(201);
38	        assertThat(replay.replay()).isTrue();
39	        // 工序卡仍只有一张
40	        Integer cards = jdbcTemplate.queryForObject(
41	                "SELECT COUNT(*) FROM operation_card WHERE card_no = ?", Integer.class, "CARD-E1");
42	        assertThat(cards).isEqualTo(1);
43	    }
44	
45	    @Test
46	    @DisplayName("同键异参返回 409，工序状态不变、工位仍被首次卡占用")
47	    void sameKeyDifferentParamsConflict() {
48	        service.dispatch(TestRequests.singlePoint("req-conflict", "CARD-E2", "S2", "N", "P1", "100.000"));
49	        var changed = TestRequests.singlePoint("req-conflict", "CARD-E2-DIFFERENT", "S2", "N", "P1", "100.000");
50	        Outcome conflict = service.dispatch(changed);
51	        assertThat(conflict.status()).isEqualTo(409);
52	        assertThat(((java.util.Map<?, ?>) conflict.body()).get("errorCode"))
53	                .isEqualTo("IDEMPOTENCY_KEY_CONFLICT");
54	        // 异参卡未创建
55	        assertThat(jdbcTemplate.queryForObject(
56	                "SELECT COUNT(*) FROM operation_card WHERE card_no = ?", Integer.class, "CARD-E2-DIFFERENT"))
57	                .isZero();
58	    }
59	
60	    @Test
61	    @DisplayName("失败请求同键重放返回首次失败结果（422 幂等），改用新键同参才执行")
62	    void failureIsIdempotent() {
63	        prepareTightenedCard("CARD-E3", "S3");
64	        var samePerson = TestRequests.inspection("req-fail", "CARD-E3", "same", "same");
65	
66	        Outcome first = service.inspect(samePerson);
67	        assertThat(first.status()).isEqualTo(422);
68	        Outcome replay = service.inspect(samePerson);
69	        assertThat(replay.status()).isEqualTo(422);
70	        assertThat(replay.replay()).isTrue();
71	        // 检验记录仍为 0（失败事务已回滚，不改变工序状态）
72	        assertThat(jdbcTemplate.queryForObject(
73	                "SELECT COUNT(*) FROM inspection_record WHERE card_id = "
74	                        + "(SELECT id FROM operation_card WHERE card_no = 'CARD-E3')", Integer.class))
75	                .isZero();
