82	    @Test
83	    @DisplayName("力矩测量重放返回首次结果，attempt 链不重复追加")
84	    void torqueReplayDoesNotDuplicate() {
85	        service.registerTool(TestRequests.tool("T1", TestRequests.TODAY));
86	        service.dispatch(TestRequests.singlePoint("d-e4", "CARD-E4", "S4", "N", "P1", "100.000"));
87	        var measure = TestRequests.torque("m-e4", "CARD-E4", "P1", "120", "op1", "T1");
88	        Outcome first = service.measure(measure);
