135	    @Override
136	    public Outcome collect(CollectionBatchRequest request) {
137	        if (request.packets() == null || request.packets().isEmpty()) {
138	            throw ApiException.badRequest("PACKETS_REQUIRED", "批量采集至少包含一个包");
139	        }
140	        if (request.packets().size() > MAX_BATCH) {
141	            throw ApiException.badRequest("BATCH_TOO_LARGE", "一次上传至多 " + MAX_BATCH + " 包");
142	        }
143	        return idempotencyExecutor.executeSuccessOnly(
144	                request.requestId(), "COLLECTION_BATCH", request, () -> doCollect(request));
145	    }
146	
147	    private Outcome doCollect(CollectionBatchRequest request) {
148	        // 会话行加写锁：同会话并发上传在此串行，相邻包不会重复消耗前缀或多算返工。
149	        CollectionRepository.SessionRow session = requireSessionForUpdate(request.sessionNo());
150	        if (request.expectedVersion() == null || request.expectedVersion() != session.version()) {
151	            throw ApiException.conflict("VERSION_CONFLICT",
152	                    "expectedVersion=" + request.expectedVersion() + " 与当前版本 " + session.version() + " 不一致");
153	        }
154	        CardRow card = requireCardById(session.cardId());
155	
156	        // 批内静态校验：序号重复、非法字段任一错误整批拒绝。
157	        Set<Integer> batchSeqs = new HashSet<>();
158	        for (CollectionPacketRequest packet : request.packets()) {
159	            if (packet.seq() == null || packet.seq() < 1) {
160	                throw ApiException.badRequest("SEQ_INVALID", "采集序号必须为从 1 开始的正整数");
161	            }
162	            if (!batchSeqs.add(packet.seq())) {
163	                throw ApiException.badRequest("DUPLICATE_SEQ_IN_BATCH", "本批内序号重复: " + packet.seq());
164	            }
165	            if (packet.pointCode() == null || packet.pointCode().isBlank()) {
166	                throw ApiException.badRequest("POINT_CODE_REQUIRED", "第 " + packet.seq() + " 包缺少点号");
167	            }
168	            if (packet.measuredTorque() == null || packet.measuredTorque().signum() <= 0) {
169	                // JSON 数字无法反序列化为 NaN/Infinity（Jackson 直接拒绝），故正数即有限正数。
170	                throw ApiException.badRequest("TORQUE_INVALID",
171	                        "第 " + packet.seq() + " 包力矩必须为有限正数");
172	            }
173	            if (packet.measuredAt() == null) {
174	                throw ApiException.badRequest("MEASURED_AT_REQUIRED",
175	                        "第 " + packet.seq() + " 包缺少 UTC 测量时刻");
176	            }
177	        }
178	        Set<String> boundPoints = new HashSet<>(collectionRepository.listPointCodes(session.id()));
179	
180	        // 归档后包只记迟到，不复活卡片（优先于会话开关状态）。
181	        if (card.status() == CardStatus.ARCHIVED) {
182	            return handleLateBatch(request, session, card, batchSeqs, boundPoints);
183	        }
184	        if (session.status() == CollectionStatus.CLOSED) {
185	            throw ApiException.unprocessable("SESSION_CLOSED",
186	                    "采集会话 " + session.sessionNo() + " 已关闭，不能再上传采集包");
